<?php
namespace Xdecaro\Plugin\Task\Decaromembership\Extension;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\Plugin\CMSPlugin; use Joomla\Component\Scheduler\Administrator\Event\ExecuteTaskEvent; use Joomla\Component\Scheduler\Administrator\Task\Status; use Joomla\Component\Scheduler\Administrator\Traits\TaskPluginTrait; use Joomla\Event\SubscriberInterface; use Throwable; use Xdecaro\Component\Decaromembership\Administrator\Extension\MembershipComponent;
final class Decaromembership extends CMSPlugin implements SubscriberInterface { use TaskPluginTrait; protected const TASKS_MAP=['decaromembership.reminders'=>['langConstPrefix'=>'PLG_TASK_DECAROMEMBERSHIP_REMINDERS','form'=>'reminders','method'=>'processReminders']]; protected $autoloadLanguage=true; public static function getSubscribedEvents():array{return ['onTaskOptionsList'=>'advertiseRoutines','onExecuteTask'=>'standardRoutineHandler','onContentPrepareForm'=>'enhanceTaskItemForm'];} protected function processReminders(ExecuteTaskEvent $event):int{try{$component=Factory::getApplication()->bootComponent('com_decaromembership');if(!$component instanceof MembershipComponent){throw new \RuntimeException('Membership component unavailable.');}$params=$event->getArgument('params');$days=max(1,min(365,(int)($params->days??30)));$limit=max(1,min(1000,(int)($params->limit??200)));$stats=$component->getReminderService()->process($days,$limit);$this->logTask(sprintf('Membership reminders: items=%d notifications=%d tasks=%d skipped=%d',$stats['items'],$stats['notifications'],$stats['tasks'],$stats['skipped']));return Status::OK;}catch(Throwable $e){$this->logTask('Membership reminders error: '.$e->getMessage(),'error');return Status::KNOCKOUT;}} }
